base = pathlib.Path('.')
for rel, b64 in data.items():
    p = base / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    clean = ''.join(b64.split())
    p.write_bytes(base64.b64decode(clean))
    print(f'created {rel}')
